}

#!/usr/bin/env python3
from __future__ import annotations

import hashlib, importlib.util, json, os, py_compile, subprocess, tempfile, time
from pathlib import Path
from typing import Any

SCHEMA="eira2_autonomous_engineering_loop_v2"
DENIED_PREFIXES=("main.py","engine/","brain/","council/","routers/","voice/","identity/","memory/","reasoning/","speech/")
MAX_ATTEMPTS_HARD=5

def sha256_bytes(data:bytes)->str: return hashlib.sha256(data).hexdigest()

def safe_rel(value:str)->str:
    p=Path(str(value or ""))
    if p.is_absolute() or not p.parts or ".." in p.parts: raise RuntimeError("unsafe_relative_path:"+str(value))
    return p.as_posix()

def core_denied(target:str)->bool:
    t=safe_rel(target); return t=="main.py" or any(t.startswith(x) for x in DENIED_PREFIXES if x!="main.py")

def atomic_json(path:Path,payload:Any)->None:
    path.parent.mkdir(parents=True,exist_ok=True); tmp=path.with_name(path.name+f".tmp.{os.getpid()}")
    tmp.write_text(json.dumps(payload,indent=2,sort_keys=True)+"\n",encoding="utf-8"); os.replace(tmp,path)

def load_module(path:Path,name:str):
    spec=importlib.util.spec_from_file_location(name,path)
    if spec is None or spec.loader is None: raise RuntimeError("module_load_failed:"+str(path))
    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod); return mod

def find_verified_engineering(root:Path):
    candidates=[root/"extensions"/"verified_engineering_ai"/"plugin.py",root/"extensions"/"verified_engineering_ai"/"verified_engineering_ai.py",root/"extensions"/"verified_engineering_ai"/"__init__.py"]
    errors=[]
    for path in candidates:
        if not path.is_file(): continue
        try:
            mod=load_module(path,"eira2_autonomous_verified_engineering"); fn=getattr(mod,"ask",None)
            if callable(fn): return fn,path
        except Exception as exc: errors.append(f"{path}:{type(exc).__name__}:{exc}")
    raise RuntimeError("verified_engineering_ask_unavailable:"+" | ".join(errors[-3:]))

def extract_candidate(value:Any)->bytes:
    if isinstance(value,bytes): return value
    if isinstance(value,str): return value.encode()
    if isinstance(value,dict):
        for key in ("candidate_bytes","candidate","content","code","text","output","replacement"):
            v=value.get(key)
            if isinstance(v,bytes): return v
            if isinstance(v,str): return v.encode()
    raise RuntimeError("verified_engineering_result_has_no_candidate")

def generate_candidate(root:Path,sandbox:Path,job:dict[str,Any],before:bytes|None,prior_failures:list[dict[str,Any]])->tuple[bytes,dict[str,Any]]:
    objective=str(job.get("objective") or "").strip(); target=safe_rel(str(job.get("target_path") or ""))
    if not objective: raise RuntimeError("autonomous_objective_required")
    if job.get("qualification_canary") is True:
        value=job.get("canary_candidate_text")
        if not isinstance(value,str) or not value: raise RuntimeError("qualification_canary_text_required")
        candidate=value.encode("utf-8")
        return candidate,{"provider":"deterministic_control_loop_canary","qualification_only":True,"candidate_sha256":sha256_bytes(candidate),"candidate_bytes":len(candidate)}
    ask,provider_path=find_verified_engineering(root)
    req={
        "schema":"eira2_verified_engineering_autonomous_candidate_v2",
        "objective":objective,
        "target_path":target,
        "sandbox_root":str(sandbox),
        "existing_source":before.decode("utf-8",errors="replace") if before is not None else None,
        "requirements":job.get("requirements") or [],
        "prior_failed_attempts":prior_failures[-3:],
        "constraints":[
            "Return a complete replacement candidate only; never mutate LIVE.",
            "Preserve compatible interfaces unless the objective explicitly requires a change.",
            "Use prior_failed_attempts as repair evidence and correct the observed failure.",
            "Do not claim verification; verification is performed by the autonomous sandbox loop."
        ]
    }
    try: result=ask(req)
    except TypeError: result=ask(json.dumps(req,sort_keys=True))
    candidate=extract_candidate(result)
    if not candidate: raise RuntimeError("empty_candidate")
    return candidate,{"provider":str(provider_path.resolve().relative_to(root.resolve())),"candidate_sha256":sha256_bytes(candidate),"candidate_bytes":len(candidate)}

def run_checks(sandbox:Path,candidate_path:Path,job:dict[str,Any])->dict[str,Any]:
    checks=[]; suffix=candidate_path.suffix.lower()
    checks.append({"name":"candidate_nonempty","ok":candidate_path.is_file() and candidate_path.stat().st_size>0})
    if suffix==".py":
        try: py_compile.compile(str(candidate_path),doraise=True); checks.append({"name":"python_compile","ok":True})
        except Exception as exc: checks.append({"name":"python_compile","ok":False,"error":f"{type(exc).__name__}:{exc}"})
    elif suffix==".json":
        try: json.loads(candidate_path.read_text(encoding="utf-8")); checks.append({"name":"json_parse","ok":True})
        except Exception as exc: checks.append({"name":"json_parse","ok":False,"error":f"{type(exc).__name__}:{exc}"})
    argv=job.get("test_argv")
    if argv is not None:
        if not isinstance(argv,list) or not argv or not all(isinstance(x,str) and x for x in argv): raise RuntimeError("test_argv_must_be_nonempty_string_list")
        timeout=max(1,min(int(job.get("test_timeout_seconds") or 300),1800))
        env={"PATH":os.environ.get("PATH",""),"PYTHONPATH":str(sandbox),"HOME":str(sandbox),"EIRA_AUTONOMOUS_SANDBOX":"1","EIRA2_CANDIDATE_PATH":str(candidate_path)}
        p=subprocess.run(argv,cwd=str(sandbox),text=True,capture_output=True,timeout=timeout,check=False,env=env)
        checks.append({"name":"requested_tests","ok":p.returncode==0,"returncode":p.returncode,"stdout_tail":(p.stdout or "")[-12000:],"stderr_tail":(p.stderr or "")[-6000:]})
    return {"checks":checks,"ok":all(x.get("ok") is True for x in checks),"evaluated_unix":time.time()}

def watcher_approve(root:Path,outer_request:dict[str,Any],evidence:dict[str,Any])->dict[str,Any]:
    path=root/"extensions"/"repair_watcher_ai"/"plugin.py"
    if not path.is_file(): raise RuntimeError("repair_watcher_missing")
    watcher=load_module(path,"eira2_autonomous_repair_watcher"); fn=getattr(watcher,"authorize_transport_request",None)
    if not callable(fn): raise RuntimeError("watcher_transport_authority_unavailable")
    approval_request={"schema":"eira2_transport_request_v1","request_id":str(outer_request.get("request_id") or "")+".sandbox_approval","operation":"deploy","autonomous_engineering":True,"sandbox_evidence":evidence,"deployment":outer_request.get("deployment") or {}}
    out=fn(approval_request)
    if not isinstance(out,dict) or out.get("authorized") is not True: raise RuntimeError("watcher_rejected_autonomous_candidate:"+json.dumps(out,sort_keys=True)[-1800:])
    return out

def prepare_candidate(root:Path,request:dict[str,Any])->dict[str,Any]:
    dep=request.get("deployment") or {}; job=dep.get("autonomous_job") or {}; target=safe_rel(str(job.get("target_path") or (dep.get("target") or {}).get("path") or ""))
    if core_denied(target) and job.get("explicit_core_authorization") is not True: raise RuntimeError("autonomous_core_boundary_denied:"+target)
    job_id=str(request.get("request_id") or "autonomous"); sandbox_root=root/"eira_probe"/"autonomous_engineering"/"sandboxes"; sandbox_root.mkdir(parents=True,exist_ok=True); sandbox=Path(tempfile.mkdtemp(prefix=job_id[:48]+"_",dir=str(sandbox_root)))
    live=root/target; before=live.read_bytes() if live.is_file() else None; before_sha=sha256_bytes(before) if before is not None else None; candidate_path=sandbox/Path(target).name; started=time.time()
    max_attempts=max(1,min(int(job.get("max_sandbox_attempts") or 3),MAX_ATTEMPTS_HARD)); attempts=[]; prior_failures=[]
    try:
        final_candidate=None; final_producer=None; final_tests=None
        for attempt in range(1,max_attempts+1):
            candidate,producer=generate_candidate(root,sandbox,{**job,"target_path":target},before,prior_failures)
            candidate_path.write_bytes(candidate); tests=run_checks(sandbox,candidate_path,job)
            row={"attempt":attempt,"candidate_sha256":sha256_bytes(candidate),"candidate_bytes":len(candidate),"producer":producer,"tests":tests}
            attempts.append(row)
            if tests.get("ok") is True:
                final_candidate=candidate; final_producer=producer; final_tests=tests; break
            prior_failures.append({"attempt":attempt,"tests":tests,"candidate_sha256":sha256_bytes(candidate)})
        evidence={
            "schema":SCHEMA,"request_id":job_id,"target_path":target,"sandbox":str(sandbox),"sandbox_isolated":True,"live_mutated_during_creation":False,
            "before_exists":before is not None,"before_sha256":before_sha,"before_bytes":len(before) if before is not None else 0,
            "objective":str(job.get("objective") or ""),"attempts":attempts,"max_sandbox_attempts":max_attempts,"started_unix":started,"evaluated_unix":time.time()
        }
        if final_candidate is None or final_tests is None or final_tests.get("ok") is not True:
            evidence["approved"]=False; evidence["failure"]="sandbox_attempts_exhausted"
            atomic_json(root/"eira_probe"/"autonomous_engineering"/"evidence"/f"{job_id}.failed.json",evidence)
            raise RuntimeError("autonomous_sandbox_tests_failed:"+json.dumps(evidence,sort_keys=True)[-3200:])
        evidence.update({"candidate_sha256":sha256_bytes(final_candidate),"candidate_bytes":len(final_candidate),"producer":final_producer,"tests":final_tests,"sandbox_tests_passed":True})
        approval=watcher_approve(root,request,evidence); evidence["watcher_approval"]=approval; evidence["approved"]=True; evidence["approval_unix"]=time.time()
        receipt=root/"eira_probe"/"autonomous_engineering"/"evidence"/f"{job_id}.json"; atomic_json(receipt,evidence)
        return {"payload":final_candidate,"target_path":target,"before_sha256":before_sha,"evidence":evidence,"evidence_path":str(receipt)}
    except Exception:
        fail=root/"eira_probe"/"autonomous_engineering"/"evidence"/f"{job_id}.failed.json"
        if not fail.exists(): atomic_json(fail,{"schema":SCHEMA,"request_id":job_id,"target_path":target,"sandbox":str(sandbox),"sandbox_isolated":True,"live_mutated_during_creation":False,"before_sha256":before_sha,"approved":False,"attempts":attempts,"failed_unix":time.time()})
        raise

#!/usr/bin/env python3
from __future__ import annotations

import hashlib, importlib.util, json, os, py_compile, re, shutil, subprocess, sys, tempfile, time
from pathlib import Path
from typing import Any

SCHEMA = "eira2_autonomous_repair_v1"
DENY_PREFIXES = (
    "main.py", "engine/", "brain/", "council/", "routers/", "voice/",
    "identity/", "memory/", "reasoning/", "speech/",
)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str | None:
    if not path.is_file(): return None
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def safe_rel(value: str) -> str:
    p = Path(str(value or ""))
    if p.is_absolute() or not p.parts or ".." in p.parts:
        raise RuntimeError("unsafe_relative_path:" + value)
    return p.as_posix()


def load_module(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError("module_load_failed:" + str(path))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def load_verified_engineering(root: Path):
    candidates = [
        root / "extensions" / "verified_engineering_ai" / "plugin.py",
        root / "extensions" / "verified_engineering_ai" / "__init__.py",
        root / "extensions" / "verified_engineering_ai.py",
    ]
    for p in candidates:
        if p.is_file():
            mod = load_module(p, "eira2_verified_engineering_runtime")
            fn = getattr(mod, "ask", None)
            if callable(fn): return fn, p
    raise RuntimeError("verified_engineering_ask_unavailable")


def load_watcher(root: Path):
    p = root / "extensions" / "repair_watcher_ai" / "plugin.py"
    if not p.is_file(): raise RuntimeError("repair_watcher_plugin_missing")
    return load_module(p, "eira2_autonomous_repair_watcher")


def watcher_authorize_candidate(root: Path, evidence: dict[str, Any]) -> dict[str, Any]:
    watcher = load_watcher(root)
    for name in ("authorize_candidate", "approve_candidate", "authorize_repair", "authorize_transport_request"):
        fn = getattr(watcher, name, None)
        if not callable(fn): continue
        payload = evidence if name != "authorize_transport_request" else {
            "schema": "eira2_transport_request_v1",
            "request_id": evidence["request_id"],
            "operation": "deploy",
            "autonomous_repair_evidence": evidence,
        }
        out = fn(payload)
        if isinstance(out, dict) and (out.get("authorized") is True or out.get("approved") is True or out.get("ok") is True):
            return {"authorized": True, "method": name, "watcher": out}
    raise RuntimeError("watcher_candidate_authorization_failed")


def extract_candidate(answer: Any) -> bytes:
    if isinstance(answer, bytes): return answer
    if isinstance(answer, str): return answer.encode("utf-8")
    if isinstance(answer, dict):
        for key in ("candidate", "content", "source", "code", "replacement"):
            value = answer.get(key)
            if isinstance(value, str): return value.encode("utf-8")
    raise RuntimeError("verified_engineering_returned_no_candidate")


def run_tests(candidate: Path, spec: dict[str, Any], sandbox: Path) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    if candidate.suffix == ".py":
        try:
            py_compile.compile(str(candidate), doraise=True)
            results.append({"name": "python_compile", "ok": True})
        except Exception as exc:
            results.append({"name": "python_compile", "ok": False, "error": f"{type(exc).__name__}:{exc}"})
    for i, test in enumerate(spec.get("tests") or []):
        if not isinstance(test, dict): continue
        argv = test.get("argv")
        if not isinstance(argv, list) or not argv or not all(isinstance(x, str) for x in argv):
            raise RuntimeError("invalid_test_argv")
        timeout = min(max(int(test.get("timeout_seconds") or 120), 1), 900)
        env = dict(os.environ)
        env["EIRA2_CANDIDATE_PATH"] = str(candidate)
        p = subprocess.run(argv, cwd=str(sandbox), text=True, capture_output=True, timeout=timeout, check=False, env=env)
        results.append({"name": str(test.get("name") or f"test_{i}"), "ok": p.returncode == 0, "returncode": p.returncode, "stdout_tail": (p.stdout or "")[-4000:], "stderr_tail": (p.stderr or "")[-4000:]})
    return {"results": results, "all_passed": bool(results) and all(r.get("ok") is True for r in results)}


def build_candidate(root: Path, request: dict[str, Any], sandbox: Path) -> tuple[Path, dict[str, Any]]:
    target_rel = safe_rel(str((request.get("target") or {}).get("path") or ""))
    if target_rel == "main.py" or any(target_rel.startswith(p) for p in DENY_PREFIXES if p.endswith("/")):
        raise RuntimeError("autonomous_core_boundary_denied:" + target_rel)
    live = (root / target_rel).resolve(); live.relative_to(root)
    current = live.read_bytes() if live.is_file() else b""
    ask, provider_path = load_verified_engineering(root)
    task = str(request.get("task") or "").strip()
    if not task: raise RuntimeError("autonomous_task_missing")
    prompt = {
        "task": task,
        "target_path": target_rel,
        "current_source": current.decode("utf-8", errors="replace"),
        "requirements": request.get("requirements") or {},
        "mode": "isolated_sandbox_candidate_only",
        "must_return_complete_replacement": True,
        "must_not_modify_live": True,
    }
    try:
        answer = ask(prompt)
    except TypeError:
        answer = ask(json.dumps(prompt, sort_keys=True))
    payload = extract_candidate(answer)
    candidate = sandbox / Path(target_rel).name
    candidate.write_bytes(payload)
    return candidate, {
        "provider": str(provider_path.relative_to(root)),
        "before_sha256": sha256_bytes(current) if current else None,
        "candidate_sha256": sha256_bytes(payload),
        "candidate_bytes": len(payload),
    }


def execute(root: Path, repo: Path, request: dict[str, Any], base, initial_auth: dict[str, Any]) -> dict[str, Any]:
    rid = str(request.get("request_id") or "")
    if request.get("autonomous_schema") not in {None, SCHEMA}: raise RuntimeError("autonomous_schema_invalid")
    target_rel = safe_rel(str((request.get("target") or {}).get("path") or ""))
    with tempfile.TemporaryDirectory(prefix="eira2_autonomous_repair_") as td:
        sandbox = Path(td)
        candidate, build = build_candidate(root, request, sandbox)
        tests = run_tests(candidate, request, sandbox)
        if tests.get("all_passed") is not True:
            raise RuntimeError("sandbox_tests_failed:" + json.dumps(tests, sort_keys=True)[-3000:])
        evidence = {
            "schema": "eira2_autonomous_repair_evidence_v1",
            "request_id": rid,
            "target_path": target_rel,
            "initial_watcher_authorization": initial_auth,
            "sandbox_isolated": True,
            "build": build,
            "tests": tests,
            "evaluated": True,
            "generated_unix": time.time(),
        }
        approval = watcher_authorize_candidate(root, evidence)
        evidence["post_test_watcher_approval"] = approval
        payload = candidate.read_bytes()
        live = root / target_rel
        before = sha256_file(live)
        lane = base._run_lane(root, repo, rid, target_rel, payload, before)
        after = sha256_file(live)
        expected = sha256_bytes(payload)
        if after != expected: raise RuntimeError("autonomous_post_deploy_sha256_mismatch")
        evidence.update({
            "builder_invoked": True,
            "before_sha256": before,
            "after_sha256": after,
            "completion_sha256": after,
            "candidate_sha256": expected,
            "lane_receipt": lane.get("lane_receipt") or {},
            "executed": True,
            "verified": True,
        })
        return evidence

#!/usr/bin/env python3
from __future__ import annotations

import argparse, importlib.util, json, os, shutil, subprocess, sys, threading, time
from pathlib import Path
from typing import Any

REPO_URL='https://github.com/domenicleonetti8-dev/ish-broadcast.git'
REQUEST_ROOT=Path('eira2_transport_bus/to_superprobe/requests')
RETURN_ROOT=Path('eira2_transport_bus/from_superprobe/receipts')
REQUEST_SCHEMA='eira2_transport_request_v1'
BASE_NAME='EIRA2_OMNIDIRECTIONAL_TRANSPORT_CONSUMER_V3.py'
HEARTBEAT_SECONDS=5
RETRY_SECONDS=8


def run(cmd:list[str],*,cwd:Path|None=None,timeout:int=600)->subprocess.CompletedProcess[str]:
    return subprocess.run(cmd,cwd=str(cwd) if cwd else None,text=True,capture_output=True,timeout=timeout,check=False)


def atomic(path:Path,obj:Any)->None:
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+f'.tmp.{os.getpid()}')
    tmp.write_text(json.dumps(obj,indent=2,sort_keys=True)+'\n',encoding='utf-8')
    os.replace(tmp,path)


def heal_git_state(repo:Path)->None:
    git=repo/'.git'
    if not git.is_dir():
        return
    if (git/'rebase-merge').exists() or (git/'rebase-apply').exists():
        run(['git','rebase','--abort'],cwd=repo,timeout=120)
    merge_head=git/'MERGE_HEAD'
    if merge_head.exists():
        run(['git','merge','--abort'],cwd=repo,timeout=120)
    for p in (git/'CHERRY_PICK_HEAD',git/'REVERT_HEAD'):
        if p.exists():
            run(['git','reset','--merge'],cwd=repo,timeout=120)
            break
    lock=git/'index.lock'
    if lock.exists():
        try:
            age=time.time()-lock.stat().st_mtime
            if age>300:
                lock.unlink()
        except OSError:
            pass


def sync_repo(repo:Path)->None:
    if not (repo/'.git').is_dir():
        if repo.exists(): shutil.rmtree(repo)
        p=run(['git','clone','--quiet',REPO_URL,str(repo)],timeout=600)
        if p.returncode: raise RuntimeError('git_clone_failed:'+(p.stdout+p.stderr)[-1800:])
    heal_git_state(repo)
    for cmd in (
        ['git','fetch','--quiet','origin','master'],
        ['git','checkout','--quiet','master'],
        ['git','reset','--hard','origin/master'],
        ['git','clean','-fd'],
    ):
        p=run(cmd,cwd=repo,timeout=600)
        if p.returncode: raise RuntimeError('git_sync_failed:'+(p.stdout+p.stderr)[-1800:])


def load_module(path:Path,name:str):
    spec=importlib.util.spec_from_file_location(name,path)
    if spec is None or spec.loader is None: raise RuntimeError('import_failed:'+str(path))
    mod=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def load_base(repo:Path):
    return load_module(repo/BASE_NAME,'eira2_transport_v6_base')


def load_watcher(root:Path):
    return load_module(root/'extensions'/'repair_watcher_ai'/'plugin.py','eira2_transport_v6_watcher')


def authorize(root:Path,request:dict[str,Any])->dict[str,Any]:
    last=''
    for n in range(12):
        try:
            watcher=load_watcher(root)
            fn=getattr(watcher,'authorize_transport_request',None)
            if callable(fn):
                out=fn(request)
                if isinstance(out,dict) and out.get('authorized') is True:
                    return out
                raise RuntimeError('watcher_rejected:'+json.dumps(out,sort_keys=True)[-1600:])
            if str(request.get('operation') or '').casefold()=='inspect':
                fallback=getattr(watcher,'inspect_once',None)
                out=fallback() if callable(fallback) else None
                if isinstance(out,dict) and out.get('ok') is True:
                    return {'authorized':True,'authorized_by':'repair_watcher_ai','operation':'inspect','watcher_version':getattr(watcher,'VERSION','legacy'),'legacy_read_only_authorization':True}
            raise RuntimeError('watcher_transport_authority_unavailable')
        except Exception as exc:
            last=f'{type(exc).__name__}:{exc}'
            if n<11: time.sleep(5)
    raise RuntimeError('watcher_unavailable_after_retries:'+last)


def publish(repo:Path,request_id:str,receipt:dict[str,Any])->str:
    sync_repo(repo)
    rel=RETURN_ROOT/f'{request_id}__receipt.json'
    atomic(repo/rel,receipt)
    p=run(['git','add',rel.as_posix()],cwd=repo,timeout=120)
    if p.returncode: raise RuntimeError('receipt_add_failed:'+(p.stdout+p.stderr)[-1200:])
    if run(['git','diff','--cached','--quiet'],cwd=repo,timeout=120).returncode!=0:
        p=run(['git','-c','user.name=EIRA Transport V6','-c','user.email=eira-transport-v6@localhost','commit','--quiet','-m',f'Return EIRA2 transport V6 receipt {request_id}'],cwd=repo,timeout=120)
        if p.returncode: raise RuntimeError('receipt_commit_failed:'+(p.stdout+p.stderr)[-1600:])
        heal_git_state(repo)
        p=run(['git','pull','--rebase','--quiet','origin','master'],cwd=repo,timeout=600)
        if p.returncode:
            heal_git_state(repo)
            p2=run(['git','fetch','--quiet','origin','master'],cwd=repo,timeout=600)
            if p2.returncode: raise RuntimeError('receipt_fetch_recovery_failed:'+(p2.stdout+p2.stderr)[-1800:])
            p2=run(['git','rebase','origin/master'],cwd=repo,timeout=600)
            if p2.returncode:
                heal_git_state(repo)
                raise RuntimeError('receipt_rebase_failed:'+(p.stdout+p.stderr+p2.stdout+p2.stderr)[-2200:])
        p=run(['git','push','--quiet','origin','master'],cwd=repo,timeout=600)
        if p.returncode: raise RuntimeError('receipt_push_failed:'+(p.stdout+p.stderr)[-1800:])
    return run(['git','rev-parse','HEAD'],cwd=repo,timeout=120).stdout.strip()


def stage(repo:Path,rid:str,op:str,digest:str,name:str,**extra:Any)->str:
    payload={
        'schema':'eira2_transport_terminal_receipt_v6',
        'request_id':rid,
        'operation':op,
        'transport_request_sha256':digest,
        'status':'IN_PROGRESS',
        'ok':None,
        'stage':name,
        'supervisor_pid':os.getpid(),
        'updated_unix':time.time(),
        **extra,
    }
    return publish(repo,rid,payload)


def request_still_current(repo:Path,source_name:str,digest:str,base)->bool:
    sync_repo(repo)
    current=repo/REQUEST_ROOT/source_name
    if not current.is_file():
        return False
    try:
        return base.sha256_bytes(current.read_bytes())==digest
    except OSError:
        return False


def add_full_sources(base,root:Path,request:dict[str,Any],evidence:dict[str,Any])->None:
    rows=[]
    for value in ((request.get('inspection') or {}).get('full_source_paths') or []):
        rel=base.safe_rel(str(value))
        p=(root/rel).resolve(); p.relative_to(root)
        if not p.is_file():
            rows.append({'path':rel,'error':'not_found'}); continue
        raw=p.read_bytes()
        rows.append({'path':rel,'bytes':len(raw),'sha256':base.sha256_bytes(raw),'source':raw.decode('utf-8',errors='replace')})
    if rows: evidence['full_sources']=rows


def process_one(root:Path,runtime:Path,repo:Path,source:Path)->bool:
    base=load_base(repo)
    raw=source.read_bytes()
    digest=base.sha256_bytes(raw)
    request=json.loads(raw.decode('utf-8'))
    rid=str(request.get('request_id') or '')
    op=str(request.get('operation') or '').casefold()
    if request.get('schema')!=REQUEST_SCHEMA or op not in {'inspect','deploy'} or not rid:
        return False
    success=runtime/'state'/f'{digest}.success.json'
    if success.exists(): return False

    started={'schema':'eira2_transport_terminal_receipt_v6','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'STARTED','ok':None,'stage':'single_checkout_execution','supervisor_pid':os.getpid(),'started_unix':time.time()}
    commit=publish(repo,rid,started)
    atomic(runtime/'local_receipts'/f'{rid}.started.json',{**started,'return_transport_commit':commit})

    try:
        sync_repo(repo)
        base=load_base(repo)
        if not request_still_current(repo,source.name,digest,base):
            retired={'schema':'eira2_transport_terminal_receipt_v6','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'SUPERSEDED_ABORTED','ok':True,'superseded':True,'builder_invoked':False,'error':None,'completed_unix':time.time()}
            commit=publish(repo,rid,retired)
            retired['return_transport_commit']=commit
            atomic(success,retired)
            atomic(runtime/'local_receipts'/f'{rid}.terminal.json',retired)
            return True

        stage(repo,rid,op,digest,'WATCHER_AUTHORIZING')
        auth=authorize(root,request)
        stage(repo,rid,op,digest,'WATCHER_AUTHORIZED',watcher_authorized=True,watcher_authorization=auth)

        if op=='inspect':
            inspect_spec=request.get('inspection') or {}
            stage_name='QUALIFYING' if inspect_spec.get('execute_source') else 'INSPECTING'
            stage(repo,rid,op,digest,stage_name,watcher_authorized=True)
            evidence=base.inspect_request(root,request,auth)
            add_full_sources(base,root,request,evidence)
            receipt={'schema':'eira2_transport_terminal_receipt_v6','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'INSPECTION_COMPLETE','ok':True,'watcher_authorized':True,'watcher_authorization':auth,'builder_invoked':False,'evidence':evidence,'error':None,'completed_unix':time.time()}
        else:
            stage(repo,rid,op,digest,'DEPLOYING',watcher_authorized=True)
            evidence=base.deploy_request(root,repo,request,auth)
            receipt={'schema':'eira2_transport_terminal_receipt_v6','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'DEPLOYED_SUCCESSFULLY','ok':True,'watcher_authorized':True,'watcher_authorization':auth,'builder_invoked':bool(evidence.get('builder_invoked')),'deployment':evidence,'completion_sha256':evidence.get('completion_sha256') or evidence.get('after_sha256'),'error':None,'completed_unix':time.time()}
        commit=publish(repo,rid,receipt)
        receipt['return_transport_commit']=commit
        atomic(success,receipt)
        atomic(runtime/'local_receipts'/f'{rid}.terminal.json',receipt)
        return True
    except Exception as exc:
        failure={'schema':'eira2_transport_terminal_receipt_v6','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'RETRYING','ok':False,'retryable':True,'retry_after_seconds':RETRY_SECONDS,'error':f'{type(exc).__name__}:{exc}'[:5000],'completed_unix':time.time()}
        atomic(runtime/'local_receipts'/f'{rid}.failure.json',failure)
        try: publish(repo,rid,failure)
        except Exception as push_exc:
            failure['publish_error']=f'{type(push_exc).__name__}:{push_exc}'[:4000]
            atomic(runtime/'local_receipts'/f'{rid}.failure.json',failure)
        time.sleep(RETRY_SECONDS)
        return False


def heartbeat_loop(runtime:Path,stop:threading.Event)->None:
    while not stop.wait(HEARTBEAT_SECONDS):
        try: atomic(runtime/'heartbeat.json',{'schema':'eira2_transport_v6_heartbeat','pid':os.getpid(),'unix':time.time(),'stage':'alive'})
        except Exception: pass


def main()->int:
    ap=argparse.ArgumentParser(); ap.add_argument('--root',required=True); ap.add_argument('--interval',type=float,default=2.0); args=ap.parse_args()
    root=Path(args.root).resolve()
    runtime=root/'eira_probe'/'transport_runtime_v6'
    repo=runtime/'repo'
    (runtime/'state').mkdir(parents=True,exist_ok=True)
    (runtime/'local_receipts').mkdir(parents=True,exist_ok=True)
    stop=threading.Event(); threading.Thread(target=heartbeat_loop,args=(runtime,stop),daemon=True).start()
    try:
        while True:
            try:
                atomic(runtime/'heartbeat.json',{'schema':'eira2_transport_v6_heartbeat','pid':os.getpid(),'unix':time.time(),'stage':'sync_repo'})
                sync_repo(repo)
                inbox=repo/REQUEST_ROOT
                for source in sorted(inbox.glob('*.json')):
                    atomic(runtime/'heartbeat.json',{'schema':'eira2_transport_v6_heartbeat','pid':os.getpid(),'unix':time.time(),'stage':'request','request_file':source.name})
                    process_one(root,runtime,repo,source)
                    sync_repo(repo)
            except Exception as exc:
                atomic(runtime/'supervisor_error.json',{'schema':'eira2_transport_v6_supervisor_error','pid':os.getpid(),'unix':time.time(),'error':f'{type(exc).__name__}:{exc}'[:5000]})
            time.sleep(max(1.0,args.interval))
    finally:
        stop.set()

if __name__=='__main__': raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import fcntl
import importlib.util
import json
import os
import time
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
V6_CANDIDATES = [
    HERE / "EIRA2_AUTONOMOUS_TRANSPORT_V6.py",
    Path("/media/domenicleonetti/easystore/EIRA/LIVE/eira_probe/transport_runtime_v6/repo/EIRA2_AUTONOMOUS_TRANSPORT_V6.py"),
]
VOLATILE_KEYS = {
    "updated_unix",
    "started_unix",
    "completed_unix",
    "published_unix",
    "return_transport_commit",
    "publish_attempt",
}
TERMINAL = {"DEPLOYED_SUCCESSFULLY", "INSPECTION_COMPLETE", "SUPERSEDED_ABORTED"}


def _load_v6():
    for path in V6_CANDIDATES:
        if path.is_file():
            spec = importlib.util.spec_from_file_location("eira2_transport_v6_runtime", path)
            if spec is None or spec.loader is None:
                continue
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            return mod
    raise RuntimeError("transport_v6_source_not_found")


v6 = _load_v6()
_original_publish = v6.publish


def _semantic(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _semantic(v) for k, v in sorted(value.items()) if k not in VOLATILE_KEYS}
    if isinstance(value, list):
        return [_semantic(v) for v in value]
    return value


def _semantic_equal(a: Any, b: Any) -> bool:
    return _semantic(a) == _semantic(b)


def publish_once(repo: Path, request_id: str, receipt: dict[str, Any]) -> str:
    """Publish only when the receipt's semantic state changed.

    Repeated timestamps, retry clocks, and publish-attempt counters never create Git commits.
    """
    v6.sync_repo(repo)
    rel = v6.RETURN_ROOT / f"{request_id}__receipt.json"
    current = repo / rel
    if current.is_file():
        try:
            old = json.loads(current.read_text(encoding="utf-8"))
            if _semantic_equal(old, receipt):
                return v6.run(["git", "rev-parse", "HEAD"], cwd=repo, timeout=120).stdout.strip()
        except Exception:
            pass
    return _original_publish(repo, request_id, receipt)


v6.publish = publish_once


def _owner_lock(root: Path):
    runtime = root / "eira_probe" / "transport_runtime_v8"
    runtime.mkdir(parents=True, exist_ok=True)
    lock_path = runtime / "owner.lock"
    fh = lock_path.open("a+")
    try:
        fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError as exc:
        fh.close()
        raise RuntimeError("transport_owner_already_active") from exc
    fh.seek(0)
    fh.truncate()
    fh.write(str(os.getpid()) + "\n")
    fh.flush()
    os.fsync(fh.fileno())
    return fh


def main() -> int:
    ap = argparse.ArgumentParser(add_help=False)
    ap.add_argument("--root", required=True)
    known, _ = ap.parse_known_args()
    root = Path(known.root).resolve()
    owner = _owner_lock(root)
    try:
        return v6.main()
    finally:
        try:
            fcntl.flock(owner.fileno(), fcntl.LOCK_UN)
        finally:
            owner.close()


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import argparse, ast, hashlib, json, os, re, shutil, subprocess, sys, time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

REPO_URL = "https://github.com/domenicleonetti8-dev/ish-broadcast.git"
REMOTE_BLUEPRINTS = Path("eira2_transport_bus/to_superprobe/blueprints")
RETURN_ROOT = Path("eira2_transport_bus/from_superprobe/deployments")
TRANSPORT_SCHEMA = "eira2_blueprint_transport_v2"
LANE_SCHEMA = "eira2_builder_blueprint_v2"
LANE_NAME = "EIRA2_BLUEPRINT_DEPLOYMENT_LANE_V4.py"
ID_RE = re.compile(r"^[A-Za-z0-9._-]{1,96}$")


def run(cmd: list[str], *, cwd: Path | None = None, timeout: int = 1200) -> subprocess.CompletedProcess[str]:
    return subprocess.run(cmd, cwd=str(cwd) if cwd else None, text=True, capture_output=True, timeout=timeout, check=False)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def atomic_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def sync_repo(work: Path) -> None:
    if not (work / ".git").is_dir():
        if work.exists():
            shutil.rmtree(work)
        p = run(["git", "clone", "--quiet", REPO_URL, str(work)], timeout=300)
        if p.returncode:
            raise RuntimeError("git_clone_failed:" + p.stderr[-800:])
    for cmd in (["git", "fetch", "--quiet", "origin", "master"], ["git", "checkout", "--quiet", "master"], ["git", "reset", "--hard", "origin/master"]):
        p = run(list(cmd), cwd=work, timeout=300)
        if p.returncode:
            raise RuntimeError("git_sync_failed:" + p.stderr[-800:])


def git_blob(repo: Path, commit: str, repo_path: str) -> bytes:
    p = subprocess.run(["git", "-C", str(repo), "show", f"{commit}:{repo_path}"], capture_output=True, timeout=120, check=False)
    if p.returncode:
        raise RuntimeError("source_blob_missing:" + p.stderr[-800:].decode(errors="replace"))
    return p.stdout


def extract_embedded_payload(source: bytes, target_path: str) -> bytes:
    text = source.decode("utf-8")
    tree = ast.parse(text)
    for node in tree.body:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            if any(isinstance(t, ast.Name) and t.id == "NEW" for t in targets):
                value = ast.literal_eval(node.value)
                if not isinstance(value, str):
                    raise RuntimeError("embedded_NEW_not_string")
                raw = value.encode("utf-8")
                if target_path.endswith(".py"):
                    compile(value, target_path, "exec")
                return raw
    raise RuntimeError("embedded_NEW_payload_missing")


def materialize_payload(repo: Path, blueprint: dict[str, Any]) -> tuple[str, str, str]:
    source = blueprint.get("source") or {}
    target = blueprint.get("target") or {}
    commit = str(source.get("commit") or "")
    path = str(source.get("path") or "")
    expected_source = str(source.get("sha256") or "").lower()
    target_path = str(target.get("path") or "")
    if not re.fullmatch(r"[0-9a-fA-F]{40}", commit):
        raise RuntimeError("source_commit_invalid")
    if not path or not target_path:
        raise RuntimeError("source_or_target_missing")
    source_bytes = git_blob(repo, commit, path)
    if expected_source and sha256_bytes(source_bytes) != expected_source:
        raise RuntimeError("source_sha256_mismatch")

    # Transport artifacts may be either direct payloads or self-contained replacement installers.
    if path.endswith(".py") and b"NEW = " in source_bytes and b"TARGET = " in source_bytes:
        payload = extract_embedded_payload(source_bytes, target_path)
    else:
        payload = source_bytes

    generated_rel = f".eira2_generated/{blueprint['blueprint_id']}/{Path(target_path).name}"
    generated = repo / generated_rel
    generated.parent.mkdir(parents=True, exist_ok=True)
    generated.write_bytes(payload)
    p = run(["git", "add", generated_rel], cwd=repo)
    if p.returncode:
        raise RuntimeError("generated_git_add_failed:" + p.stderr[-500:])
    p = run([
        "git", "-c", "user.name=EIRA Transport Materializer", "-c", "user.email=eira-transport@localhost",
        "commit", "--quiet", "-m", f"Materialize {blueprint['blueprint_id']} payload",
    ], cwd=repo)
    if p.returncode:
        raise RuntimeError("generated_commit_failed:" + p.stderr[-500:])
    synthetic_commit = run(["git", "rev-parse", "HEAD"], cwd=repo).stdout.strip()
    return synthetic_commit, generated_rel, sha256_bytes(payload)


def watcher_version(root: Path) -> str | None:
    path = root / "extensions" / "repair_watcher_ai" / "plugin.py"
    if not path.is_file():
        return None
    m = re.search(r"^VERSION\s*=\s*[\"']([^\"']+)", path.read_text(encoding="utf-8", errors="replace"), re.M)
    return m.group(1) if m else None


def read_json(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {}
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def publish_receipt(work: Path, rel: Path) -> str:
    # Drop the local synthetic payload commit before publishing transport evidence.
    p = run(["git", "reset", "--hard", "origin/master"], cwd=work)
    if p.returncode:
        raise RuntimeError("git_reset_before_publish_failed:" + p.stderr[-500:])
    p = run(["git", "add", rel.as_posix()], cwd=work)
    if p.returncode:
        raise RuntimeError("receipt_git_add_failed:" + p.stderr[-500:])
    diff = run(["git", "diff", "--cached", "--quiet"], cwd=work)
    if diff.returncode == 0:
        return run(["git", "rev-parse", "HEAD"], cwd=work).stdout.strip()
    p = run([
        "git", "-c", "user.name=EIRA Return Transport", "-c", "user.email=eira-return@localhost",
        "commit", "--quiet", "-m", "Return EIRA2 deployment receipt",
    ], cwd=work)
    if p.returncode:
        raise RuntimeError("receipt_commit_failed:" + p.stderr[-500:])
    p = run(["git", "pull", "--rebase", "--quiet", "origin", "master"], cwd=work, timeout=300)
    if p.returncode:
        raise RuntimeError("receipt_rebase_failed:" + p.stderr[-800:])
    p = run(["git", "push", "--quiet", "origin", "master"], cwd=work, timeout=300)
    if p.returncode:
        raise RuntimeError("receipt_push_failed:" + p.stderr[-800:])
    return run(["git", "rev-parse", "HEAD"], cwd=work).stdout.strip()


def process_blueprint(root: Path, work: Path, src: Path, state_dir: Path) -> dict[str, Any]:
    raw = src.read_bytes()
    digest = sha256_bytes(raw)
    blueprint = json.loads(raw.decode("utf-8"))
    if not isinstance(blueprint, dict) or blueprint.get("schema") != TRANSPORT_SCHEMA:
        return {"ignored": True, "path": src.name}
    blueprint_id = str(blueprint.get("blueprint_id") or "")
    if not ID_RE.fullmatch(blueprint_id):
        raise RuntimeError("invalid_blueprint_id")
    done = state_dir / f"{digest}.json"
    if done.exists():
        return {"already_handled": True, "blueprint_id": blueprint_id}

    target = blueprint.get("target") or {}
    target_path = str(target.get("path") or "")
    before_expected = str(target.get("expected_before_sha256") or "").lower()
    live_target = root / target_path
    before_actual = sha256_file(live_target) if live_target.is_file() else None
    transaction_id = f"{int(time.time())}-{digest[:12]}"
    receipt_rel = RETURN_ROOT / f"{blueprint_id}__{transaction_id}__receipt.json"
    receipt_abs = work / receipt_rel
    error: str | None = None
    lane_proc: subprocess.CompletedProcess[str] | None = None
    after_actual: str | None = before_actual
    payload_sha: str | None = None

    try:
        if before_expected and before_actual != before_expected:
            raise RuntimeError(f"live_before_hash_mismatch:{before_actual}")
        synthetic_commit, generated_rel, payload_sha = materialize_payload(work, blueprint)
        local_packet_dir = root / "eira_probe" / "transport_inbox" / "materialized_blueprints"
        local_packet_dir.mkdir(parents=True, exist_ok=True)
        packet_path = local_packet_dir / f"{blueprint_id}__{transaction_id}.json"
        packet = {
            "schema": LANE_SCHEMA,
            "packet_id": f"{blueprint_id}-{transaction_id}"[:96],
            "apply": True,
            "source_commit": synthetic_commit,
            "payloads": [{
                "repo_path": generated_rel,
                "target_path": target_path,
                "before_sha256": before_expected,
            }],
        }
        atomic_json(packet_path, packet)
        lane = work / LANE_NAME
        lane_proc = run([
            sys.executable, str(lane), "--root", str(root), "--packet", str(packet_path),
            "--source-repo-root", str(work),
        ], cwd=root, timeout=1800)
        after_actual = sha256_file(live_target) if live_target.is_file() else None
        if lane_proc.returncode:
            raise RuntimeError("deployment_lane_failed:" + (lane_proc.stderr or lane_proc.stdout)[-1200:])
    except Exception as exc:
        error = f"{type(exc).__name__}:{exc}"[:2000]
        after_actual = sha256_file(live_target) if live_target.is_file() else None

    packet_id = f"{blueprint_id}-{transaction_id}"[:96]
    lane_receipt_path = root / "eira_probe" / "blueprint_receipts" / f"{packet_id}.lane_v4.json"
    builder_receipt_path = root / "eira_probe" / "eira2_builder_receipt.json"
    superprobe_path = root / "eira_probe" / "eira2_superprobe_report.json"
    lane_receipt = read_json(lane_receipt_path)
    builder_receipt = read_json(builder_receipt_path)
    superprobe = read_json(superprobe_path)

    watcher_authorized = bool(lane_proc and lane_proc.returncode == 0 and lane_receipt.get("status") == "accepted")
    builder_deployed = bool(watcher_authorized and after_actual and after_actual != before_actual)
    package_ok = bool(superprobe.get("package_identity_ok") is True)
    superprobe_ok = bool(superprobe.get("ok") is True)
    discrepancies = superprobe.get("discrepancy_count")
    evidence_fp = superprobe.get("evidence_fingerprint") or superprobe.get("shared_evidence_fingerprint")
    rollback = bool(builder_receipt.get("rollback_performed") is True or builder_receipt.get("rolled_back") is True)

    if rollback:
        status = "ROLLED_BACK"
    elif error is None and watcher_authorized and builder_deployed and package_ok and superprobe_ok and discrepancies == 0:
        status = "DEPLOYED_SUCCESSFULLY"
    else:
        status = "DEPLOYMENT_FAILED"

    source_checks = {}
    if live_target.is_file() and target_path == "eira2/live.py":
        text = live_target.read_text(encoding="utf-8", errors="replace")
        source_checks = {
            "v1_text_route_present": '"/v1/text"' in text,
            "v1_listen_route_present": '"/v1/listen"' in text,
            "native_pcm_transcription_bound": "runtime.native_input.transcribe_pcm" in text,
            "canonical_runtime_process_bound": "runtime.process" in text,
        }
    acceptance_results = {
        "target_hash_changed": bool(after_actual and after_actual != before_actual),
        "payload_sha256_matches_target": bool(payload_sha and after_actual == payload_sha),
        "package_identity_ok": package_ok,
        "superprobe_ok": superprobe_ok,
        "superprobe_zero_discrepancy": discrepancies == 0,
        "single_target_only": True,
        "runtime_source_checks": source_checks,
        "live_http_roundtrip_verified": False,
        "note": "HTTP roundtrip requires the live process to be running the newly deployed file; this receipt does not fake that check.",
    }

    receipt = {
        "schema": "eira2_immediate_deployment_return_receipt_v1",
        "blueprint_id": blueprint_id,
        "transaction_id": transaction_id,
        "status": status,
        "completed_utc": utc_now(),
        "watcher_authorized": watcher_authorized,
        "watcher_version": watcher_version(root),
        "builder_deployed": builder_deployed,
        "builder_receipt": str(builder_receipt_path) if builder_receipt_path.is_file() else None,
        "target_path": target_path,
        "before_sha256": before_actual,
        "after_sha256": after_actual,
        "payload_sha256": payload_sha,
        "package_identity_ok": package_ok,
        "superprobe_schema": superprobe.get("schema"),
        "superprobe_ok": superprobe_ok,
        "superprobe_discrepancy_count": discrepancies,
        "superprobe_evidence_fingerprint": evidence_fp,
        "acceptance_results": acceptance_results,
        "rollback_performed": rollback,
        "error": error,
        "lane_receipt": str(lane_receipt_path) if lane_receipt_path.is_file() else None,
        "transport_blueprint_sha256": digest,
    }

    # Preserve the receipt while returning the repo to origin/master.
    receipt_copy = json.dumps(receipt, indent=2, sort_keys=True) + "\n"
    run(["git", "reset", "--hard", "origin/master"], cwd=work)
    receipt_abs.parent.mkdir(parents=True, exist_ok=True)
    receipt_abs.write_text(receipt_copy, encoding="utf-8")
    return_commit = publish_receipt(work, receipt_rel)
    receipt["return_transport_commit"] = return_commit
    atomic_json(done, receipt)
    return receipt


def process_once(root: Path, work: Path, state_dir: Path) -> list[dict[str, Any]]:
    sync_repo(work)
    results: list[dict[str, Any]] = []
    remote = work / REMOTE_BLUEPRINTS
    for src in sorted(remote.glob("*.json")):
        try:
            result = process_blueprint(root, work, src, state_dir)
            if not result.get("ignored") and not result.get("already_handled"):
                results.append(result)
            # Each publish may update origin; resync before the next blueprint.
            sync_repo(work)
        except Exception as exc:
            results.append({"status": "CONSUMER_ERROR", "path": src.name, "error": f"{type(exc).__name__}:{exc}"})
            sync_repo(work)
    return results


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default="/media/domenicleonetti/easystore/EIRA/LIVE")
    ap.add_argument("--work", default="/tmp/eira2_bidirectional_transport_v1")
    ap.add_argument("--interval", type=float, default=2.0)
    ap.add_argument("--once", action="store_true")
    args = ap.parse_args()
    root = Path(args.root).expanduser().resolve()
    work = Path(args.work).expanduser().resolve()
    state = root / "eira_probe" / "bidirectional_consumer_state_v1"
    if not root.is_dir():
        raise SystemExit("EIRA_ROOT_MISSING")
    state.mkdir(parents=True, exist_ok=True)
    while True:
        try:
            rows = process_once(root, work, state)
            if rows:
                print(json.dumps({"EIRA2_BIDIRECTIONAL_CONSUMER": "PASS", "results": rows}, indent=2), flush=True)
        except Exception as exc:
            print(json.dumps({"EIRA2_BIDIRECTIONAL_CONSUMER": "FAIL", "error": f"{type(exc).__name__}:{exc}"}, indent=2), file=sys.stderr, flush=True)
            if args.once:
                return 2
        if args.once:
            return 0
        time.sleep(max(0.5, args.interval))


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import argparse, hashlib, json, os, shutil, subprocess, sys, time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

SCHEMA = "eira2_bidirectional_transport_v2"
REPO_URL = "https://github.com/domenicleonetti8-dev/ish-broadcast.git"
DEFAULT_ROOT = Path("/media/domenicleonetti/easystore/EIRA/LIVE")
DEFAULT_STATE = Path.home() / ".local" / "state" / "eira2-transport-v2"
IN_LANES = ("requests", "blueprints", "jobs", "builds", "artifacts")
OUT_LANES = ("receipts", "jobs", "builds", "artifacts", "diagnostics")
REMOTE_IN = Path("eira2_transport_bus/to_superprobe")
REMOTE_OUT = Path("eira2_transport_bus/from_superprobe")
BLUEPRINT_CONSUMER = "EIRA2_BIDIRECTIONAL_BLUEPRINT_CONSUMER_V1.py"


def utc() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for b in iter(lambda: f.read(1024 * 1024), b""):
            h.update(b)
    return h.hexdigest()


def atomic_json(p: Path, obj: Any) -> None:
    p.parent.mkdir(parents=True, exist_ok=True)
    t = p.with_name(p.name + f".tmp.{os.getpid()}")
    t.write_text(json.dumps(obj, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(t, p)


def run(cmd: list[str], cwd: Path | None = None, timeout: int = 300) -> subprocess.CompletedProcess[str]:
    return subprocess.run(cmd, cwd=str(cwd) if cwd else None, text=True, capture_output=True, timeout=timeout, check=False)


def ensure_dirs(state: Path) -> None:
    for lane in IN_LANES:
        (state / "inbox" / lane).mkdir(parents=True, exist_ok=True)
    for lane in OUT_LANES:
        (state / "outbox" / lane).mkdir(parents=True, exist_ok=True)
    (state / "handled").mkdir(parents=True, exist_ok=True)
    (state / "runtime").mkdir(parents=True, exist_ok=True)


def sync_repo(state: Path) -> Path:
    repo = state / "repo"
    if not (repo / ".git").is_dir():
        if repo.exists():
            shutil.rmtree(repo)
        p = run(["git", "clone", "--quiet", REPO_URL, str(repo)], timeout=600)
        if p.returncode:
            raise RuntimeError("git_clone_failed:" + p.stderr[-1200:])
    for cmd in (["git", "fetch", "--quiet", "origin", "master"], ["git", "checkout", "--quiet", "master"], ["git", "reset", "--hard", "origin/master"]):
        p = run(list(cmd), cwd=repo, timeout=300)
        if p.returncode:
            raise RuntimeError("git_sync_failed:" + p.stderr[-1200:])
    return repo


def mirror_inbound(repo: Path, state: Path) -> dict[str, int]:
    counts: dict[str, int] = {}
    for lane in IN_LANES:
        src = repo / REMOTE_IN / lane
        dst = state / "inbox" / lane
        n = 0
        if src.is_dir():
            for p in sorted(src.iterdir()):
                if not p.is_file():
                    continue
                digest = sha256_file(p)
                marker = state / "handled" / f"mirror__{lane}__{digest}.json"
                if marker.exists():
                    continue
                target = dst / p.name
                if not target.exists() or sha256_file(target) != digest:
                    shutil.copy2(p, target)
                atomic_json(marker, {"schema": SCHEMA, "lane": lane, "name": p.name, "sha256": digest, "mirrored_utc": utc()})
                n += 1
        counts[lane] = n
    return counts


def git_publish(repo: Path, rels: list[Path], message: str) -> str | None:
    if not rels:
        return None
    p = run(["git", "fetch", "--quiet", "origin", "master"], cwd=repo, timeout=300)
    if p.returncode:
        raise RuntimeError("publish_fetch_failed:" + p.stderr[-800:])
    p = run(["git", "reset", "--hard", "origin/master"], cwd=repo, timeout=300)
    if p.returncode:
        raise RuntimeError("publish_reset_failed:" + p.stderr[-800:])
    p = run(["git", "add", *[r.as_posix() for r in rels]], cwd=repo, timeout=120)
    if p.returncode:
        raise RuntimeError("publish_add_failed:" + p.stderr[-800:])
    if run(["git", "diff", "--cached", "--quiet"], cwd=repo, timeout=120).returncode == 0:
        return run(["git", "rev-parse", "HEAD"], cwd=repo).stdout.strip()
    p = run(["git", "-c", "user.name=EIRA2 Bidirectional Transport", "-c", "user.email=eira2-transport@localhost", "commit", "--quiet", "-m", message], cwd=repo, timeout=120)
    if p.returncode:
        raise RuntimeError("publish_commit_failed:" + p.stderr[-1000:])
    p = run(["git", "pull", "--rebase", "--quiet", "origin", "master"], cwd=repo, timeout=300)
    if p.returncode:
        raise RuntimeError("publish_rebase_failed:" + p.stderr[-1200:])
    p = run(["git", "push", "--quiet", "origin", "master"], cwd=repo, timeout=300)
    if p.returncode:
        raise RuntimeError("publish_push_failed:" + p.stderr[-1200:])
    return run(["git", "rev-parse", "HEAD"], cwd=repo).stdout.strip()


def publish_outbound(repo: Path, state: Path) -> dict[str, int]:
    copied: list[Path] = []
    counts: dict[str, int] = {}
    for lane in OUT_LANES:
        src = state / "outbox" / lane
        n = 0
        for p in sorted(src.iterdir()):
            if not p.is_file():
                continue
            digest = sha256_file(p)
            marker = state / "handled" / f"publish__{lane}__{digest}.json"
            if marker.exists():
                continue
            rel = REMOTE_OUT / lane / p.name
            target = repo / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, target)
            copied.append(rel)
            atomic_json(marker, {"schema": SCHEMA, "lane": lane, "name": p.name, "sha256": digest, "queued_utc": utc()})
            n += 1
        counts[lane] = n
    if copied:
        commit = git_publish(repo, copied, "Return EIRA2 bidirectional transport payloads")
        for marker in (state / "handled").glob("publish__*.json"):
            try:
                data = json.loads(marker.read_text(encoding="utf-8"))
                if "commit" not in data:
                    data["commit"] = commit
                    data["published_utc"] = utc()
                    atomic_json(marker, data)
            except Exception:
                pass
    return counts


def mount_snapshot(root: Path) -> dict[str, Any]:
    # This is intentionally /proc based: no stat/open on the NTFS tree.
    rows = []
    try:
        for line in Path("/proc/self/mountinfo").read_text(encoding="utf-8", errors="replace").splitlines():
            if str(root).startswith(line.split()[4].replace("\\040", " ")):
                rows.append(line)
    except Exception as exc:
        return {"ok": False, "error": f"{type(exc).__name__}:{exc}", "rows": []}
    return {"ok": bool(rows), "rows": rows[-8:]}


def d_state_snapshot() -> list[dict[str, str]]:
    p = run(["ps", "-eo", "pid=,stat=,comm=,wchan="], timeout=30)
    rows = []
    for line in p.stdout.splitlines():
        parts = line.split(None, 3)
        if len(parts) >= 3 and parts[1].startswith("D"):
            rows.append({"pid": parts[0], "stat": parts[1], "comm": parts[2], "wchan": parts[3] if len(parts) > 3 else ""})
    return rows


def storage_admission(root: Path) -> tuple[bool, dict[str, Any]]:
    mounts = mount_snapshot(root)
    drows = d_state_snapshot()
    ntfs_blocked = [r for r in drows if "ntfs" in r.get("wchan", "").lower() or r.get("comm") in {"tar", "python3", "bash"}]
    ok = bool(mounts.get("ok")) and not ntfs_blocked
    return ok, {"mount": mounts, "d_state": drows, "blocked_candidates": ntfs_blocked}


def blueprint_worker_tick(repo: Path, root: Path, state: Path) -> dict[str, Any]:
    runtime = state / "runtime"
    pidfile = runtime / "blueprint_worker.pid"
    statusfile = runtime / "blueprint_worker.json"
    if pidfile.exists():
        try:
            pid = int(pidfile.read_text().strip())
            os.kill(pid, 0)
            return {"state": "RUNNING", "pid": pid}
        except Exception:
            pidfile.unlink(missing_ok=True)
    pending = list((state / "inbox" / "blueprints").glob("*.json"))
    if not pending:
        return {"state": "IDLE"}
    ok, evidence = storage_admission(root)
    if not ok:
        atomic_json(statusfile, {"schema": SCHEMA, "state": "STORAGE_BLOCKED", "utc": utc(), "evidence": evidence})
        return {"state": "STORAGE_BLOCKED", "evidence": evidence}
    consumer = repo / BLUEPRINT_CONSUMER
    if not consumer.is_file():
        return {"state": "ERROR", "error": "blueprint_consumer_missing"}
    log = runtime / "blueprint_worker.log"
    with log.open("ab") as fh:
        proc = subprocess.Popen([sys.executable, str(consumer), "--root", str(root), "--work", str(state / "blueprint-work"), "--once"], cwd=str(Path.home()), stdout=fh, stderr=subprocess.STDOUT, start_new_session=True)
    pidfile.write_text(str(proc.pid) + "\n")
    atomic_json(statusfile, {"schema": SCHEMA, "state": "STARTED", "pid": proc.pid, "utc": utc(), "evidence": evidence})
    return {"state": "STARTED", "pid": proc.pid}


def emit(state: Path, lane: str, source: Path, name: str | None) -> dict[str, Any]:
    if lane not in OUT_LANES:
        raise SystemExit(f"invalid outbound lane: {lane}")
    if not source.is_file():
        raise SystemExit("source file missing")
    dst = state / "outbox" / lane / (name or source.name)
    shutil.copy2(source, dst)
    return {"schema": SCHEMA, "queued": True, "lane": lane, "path": str(dst), "sha256": sha256_file(dst)}


def status(state: Path, root: Path) -> dict[str, Any]:
    ok, evidence = storage_admission(root)
    return {
        "schema": SCHEMA,
        "utc": utc(),
        "control_plane": str(state),
        "control_plane_on_live_drive": str(state).startswith(str(root)),
        "live_root": str(root),
        "storage_admitted": ok,
        "storage_evidence": evidence,
        "inbox": {lane: len(list((state / "inbox" / lane).glob("*"))) for lane in IN_LANES},
        "outbox": {lane: len(list((state / "outbox" / lane).glob("*"))) for lane in OUT_LANES},
    }


def once(root: Path, state: Path) -> dict[str, Any]:
    ensure_dirs(state)
    repo = sync_repo(state)
    inbound = mirror_inbound(repo, state)
    worker = blueprint_worker_tick(repo, root, state)
    repo = sync_repo(state)
    outbound = publish_outbound(repo, state)
    s = status(state, root)
    heartbeat = {"schema": SCHEMA, "utc": utc(), "inbound": inbound, "worker": worker, "outbound": outbound, "status": s}
    atomic_json(state / "runtime" / "heartbeat.json", heartbeat)
    return heartbeat


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=str(DEFAULT_ROOT))
    ap.add_argument("--state", default=str(DEFAULT_STATE))
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("once")
    d = sub.add_parser("daemon"); d.add_argument("--interval", type=float, default=3.0)
    sub.add_parser("status")
    e = sub.add_parser("emit"); e.add_argument("lane", choices=OUT_LANES); e.add_argument("source"); e.add_argument("--name")
    args = ap.parse_args()
    root = Path(args.root).expanduser()
    state = Path(args.state).expanduser()
    ensure_dirs(state)
    if args.cmd == "status":
        print(json.dumps(status(state, root), indent=2)); return 0
    if args.cmd == "emit":
        print(json.dumps(emit(state, args.lane, Path(args.source).expanduser(), args.name), indent=2)); return 0
    if args.cmd == "once":
        print(json.dumps(once(root, state), indent=2)); return 0
    while True:
        try:
            print(json.dumps(once(root, state), separators=(",", ":")), flush=True)
        except Exception as exc:
            atomic_json(state / "runtime" / "last_error.json", {"schema": SCHEMA, "utc": utc(), "error": f"{type(exc).__name__}:{exc}"})
            print(json.dumps({"EIRA2_BIDIRECTIONAL_TRANSPORT_V2": "FAIL", "error": f"{type(exc).__name__}:{exc}"}), file=sys.stderr, flush=True)
        time.sleep(max(1.0, args.interval))


if __name__ == "__main__":
    raise SystemExit(main())

