        {"format":"json","page-size":max(1,min(page_size,100)),"page":max(1,page)},
    ]
    last = None
    for params in candidates:
        try:
            data = _http_json(PROVIDERS["usgs_publications"]["endpoint"] + "?" + urllib.parse.urlencode(params))
