def _autonomous_deploy(root: Path, work: Path, request: dict[str, Any], auth: dict[str, Any]) -> dict[str, Any]:
    auto = _load(HERE / "EIRA2_AUTONOMOUS_ENGINEERING_LOOP_V1.py", "eira2_autonomous_engineering_v1_runtime")
